def close_year(self, year, equity="3000"):
    """Post `year`'s closing entry: every income and expense account's
    balance up to December 31, brought to zero against `equity`. The
    entry, or None when there is nothing to close."""
    end = datetime.date(year, 12, 31)
    memo = f"Close {year}"
    if any(e.memo == memo for e in self.entries):
        raise ValueError(f"{year} is closed already")
    lines = []
    for account in self.chart:
        if account.kind in ("income", "expense"):
            raw = sum(line.cents for _, line in self.lines(account.code, until=end))
            if raw:
                lines.append(Line(account.code, -raw))
    if not lines:
        return None
    lines.append(Line(equity, -sum(line.cents for line in lines)))
    return self.post(Entry(end, memo, lines))

